/**
 * 假的 `@deepseek-ai/dsh-tools`，只用于离线端到端测试。
 *
 * 真实实现由 DSH 在运行时提供（loader 把它注册进工具注册表再校验 JSON Schema）。
 * 这里做的最小替身只保证 `defineTool(options) → options`，使 `createTool()` 能在
 * DSH 之外被调用，从而让 `execute()` 的整条链路（建任务 → 轮询 → 下载 → 落盘 →
 * 元数据 → 迭代）可以在零网络、零花费的前提下被真实执行和断言。
 *
 * 文件名带 `.test-stub.mjs` 后缀，并放在 `test/node_modules/` 下：它只在测试时被
 * Node 的目录解析规则找到，绝不会被 DSH 加载。
 */
export function defineTool(options) {
  if (options === null || typeof options !== 'object') throw new TypeError('defineTool 需要选项对象')
  if (typeof options.name !== 'string' || options.name.length === 0) throw new TypeError('defineTool 需要 name')
  if (typeof options.execute !== 'function') throw new TypeError('defineTool 需要 execute')
  return options
}

export default { defineTool }
